
const WORDS=[{"id": 0, "w": "表现", "p": "biǎoxiàn", "t": "动词／名词", "m": "thể hiện; biểu hiện", "coll": "表现出色、表现良好", "s": "她在这次比赛中表现出色，得到了老师的表扬。"}, {"id": 1, "w": "突出", "p": "tūchū", "t": "形容词", "m": "nổi bật, nổi trội", "coll": "成绩突出、突出的特点", "s": "这位同学的学习成绩一直很突出。"}, {"id": 2, "w": "文学家", "p": "wénxuéjiā", "t": "名词", "m": "nhà văn", "coll": "一位文学家、著名文学家", "s": "这本书介绍了一位文学家的成长经历。"}, {"id": 3, "w": "算", "p": "suàn", "t": "动词", "m": "coi là, xem là", "coll": "算得上、算是", "s": "这次的任务并不难，一个小时应该算够了。"}, {"id": 4, "w": "地道", "p": "dìdao", "t": "形容词", "m": "đích thực, chân chính, chính cống", "coll": "地道的汉语、地道的家乡菜", "s": "这家餐馆的厨师会做地道的家乡菜。"}, {"id": 5, "w": "行家", "p": "hángjia", "t": "名词", "m": "người trong nghề, người thạo nghề", "coll": "一位行家、行家里手", "s": "他修理自行车很有经验，可以说是个行家。"}, {"id": 6, "w": "亲自", "p": "qīnzì", "t": "副词", "m": "tự, đích thân", "coll": "亲自参加、亲自做饭", "s": "为了表示感谢，她亲自做了一桌菜。"}, {"id": 7, "w": "见解", "p": "jiànjiě", "t": "名词", "m": "cách nhìn, quan niệm", "coll": "独特的见解、提出见解", "s": "讨论时，他提出了自己独特的见解。"}, {"id": 8, "w": "近代", "p": "jìndài", "t": "名词", "m": "thời cận đại (TQ: 1840-1919)", "coll": "近代文学、近代历史", "s": "他对中国近代的文学很感兴趣。"}, {"id": 9, "w": "时尚", "p": "shíshàng", "t": "名词", "m": "mốt, thời trang", "coll": "时尚杂志、追求时尚", "s": "这本时尚杂志介绍了今年流行的服装风格。"}, {"id": 10, "w": "写作", "p": "xiězuò", "t": "动词", "m": "sáng tác", "coll": "从事写作、坚持写作", "s": "她从大学开始就一直坚持写作。"}, {"id": 11, "w": "点心", "p": "diǎnxin", "t": "名词", "m": "bánh ngọt, điểm tâm", "coll": "一盒点心、品尝点心", "s": "客人来了，妈妈端出了一盘精致的点心。"}, {"id": 12, "w": "作为", "p": "zuòwéi", "t": "动词／介词", "m": "coi như; với tư cách", "coll": "作为代表、作为礼物", "s": "作为班长，他总是主动帮助同学。"}, {"id": 13, "w": "学问", "p": "xuéwen", "t": "名词", "m": "tri thức, học thức", "coll": "很有学问、做学问", "s": "这位老人很有学问，我们都喜欢听他讲故事。"}, {"id": 14, "w": "讲究", "p": "jiǎngjiu", "t": "动词／形容词", "m": "chú ý, coi trọng; đẹp đẽ", "coll": "讲究方法、讲究卫生", "s": "做事情要讲究方法，不能只靠着急。"}, {"id": 15, "w": "平均", "p": "píngjūn", "t": "动词", "m": "trung bình", "coll": "平均分配、平均分成五份", "s": "大家把这笔钱平均分成了五份。"}, {"id": 16, "w": "胡同", "p": "hútòng", "t": "名词", "m": "ngõ hẻm", "coll": "一条胡同、胡同里的生活", "s": "沿着这条胡同往前走，就能看到那家书店。"}, {"id": 17, "w": "位于", "p": "wèiyú", "t": "动词", "m": "nằm ở", "coll": "位于市中心、位于北部", "s": "这座图书馆位于城市的中心地带。"}, {"id": 18, "w": "首", "p": "shǒu", "t": "名词／量词", "m": "người (vật) đứng đầu; bài (thơ)", "coll": "一首诗、一首歌", "s": "她在晚会上为大家唱了一首歌。"}, {"id": 19, "w": "豪华", "p": "háohuá", "t": "形容词", "m": "sang trọng, lộng lẫy", "coll": "豪华的酒店、装修豪华", "s": "这家酒店装修得很豪华，服务也很好。"}, {"id": 20, "w": "光临", "p": "guānglín", "t": "动词", "m": "đến dự, hay lui tới", "coll": "欢迎光临、再次光临", "s": "感谢您的支持，欢迎您再次光临本店。"}, {"id": 21, "w": "交际", "p": "jiāojì", "t": "动词", "m": "xã giao, sự giao thiệp", "coll": "善于交际、交际能力", "s": "参加各种活动，可以提高我们的交际能力。"}, {"id": 22, "w": "大方", "p": "dàfang", "t": "形容词", "m": "rộng rãi, hào phóng", "coll": "待人大方、出手大方", "s": "他待人大方，经常请朋友们吃饭。"}, {"id": 23, "w": "好客", "p": "hàokè", "t": "动词", "m": "hiếu khách, mến khách", "coll": "热情好客、好客的主人", "s": "这里的居民热情好客，让我们感到很温暖。"}, {"id": 24, "w": "呼朋唤友", "p": "hūpéng huànyǒu", "t": "词组", "m": "mời mọc bạn bè", "coll": "呼朋唤友去郊游、呼朋唤友来做客", "s": "每到周末，他就呼朋唤友，一起到郊外散步。"}, {"id": 25, "w": "招待", "p": "zhāodài", "t": "动词", "m": "chiêu đãi, thiết đãi", "coll": "招待客人、热情招待", "s": "主人准备了丰盛的晚饭，热情地招待客人。"}, {"id": 26, "w": "高档", "p": "gāodàng", "t": "形容词", "m": "hảo hạng, cao cấp", "coll": "高档家具、高档商品", "s": "这家商店主要出售高档家具。"}, {"id": 27, "w": "胃口", "p": "wèikǒu", "t": "名词", "m": "khẩu vị, sự thèm ăn", "coll": "胃口很好、没有胃口", "s": "今天运动了一个下午，我胃口特别好。"}, {"id": 28, "w": "明明", "p": "míngmíng", "t": "副词", "m": "rõ ràng, chắc chắn", "coll": "明明知道、明明看见", "s": "他明明知道答案，却不愿意告诉大家。"}, {"id": 29, "w": "胃", "p": "wèi", "t": "名词", "m": "dạ dày, bao tử", "coll": "胃不舒服、胃里的食物", "s": "他今天胃不太舒服，只吃了一点儿粥。"}, {"id": 30, "w": "戒", "p": "jiè", "t": "动词", "m": "cai, bỏ", "coll": "戒烟、戒掉坏习惯", "s": "为了家人的健康，他决定戒烟。"}, {"id": 31, "w": "保存", "p": "bǎocún", "t": "动词", "m": "giữ gìn, bảo tồn", "coll": "保存资料、保存完好", "s": "这些老照片保存得很好，看起来仍然很清楚。"}, {"id": 32, "w": "资料", "p": "zīliào", "t": "名词", "m": "tài liệu, tư liệu", "coll": "查找资料、学习资料", "s": "写文章前，我们需要查找相关资料。"}, {"id": 33, "w": "曾经", "p": "céngjīng", "t": "副词", "m": "đã từng", "coll": "曾经去过、曾经做过", "s": "她曾经在这座城市工作过三年。"}, {"id": 34, "w": "形容", "p": "xíngróng", "t": "动词", "m": "hình dung, miêu tả", "coll": "形容景色、难以形容", "s": "眼前的景色太美了，我不知道该怎样形容。"}, {"id": 35, "w": "朦胧", "p": "ménglóng", "t": "形容词", "m": "lờ mờ, mơ màng", "coll": "朦胧的月色、朦胧的灯光", "s": "夜色中，远处的灯光显得十分朦胧。"}, {"id": 36, "w": "悠悠", "p": "yōuyōu", "t": "形容词", "m": "thong thả, ung dung", "coll": "白云悠悠、悠悠地走", "s": "午后，几朵白云在蓝天上悠悠地飘着。"}, {"id": 37, "w": "形象", "p": "xíngxiàng", "t": "形容词", "m": "sinh động, hình tượng", "coll": "形象地说明、生动形象", "s": "老师用一个小故事，形象地说明了这个道理。"}];
const CHUNKS=[["她", "在这次比赛中", "表现出色，", "得到了老师的表扬。"], ["这位同学", "的学习成绩", "一直", "很突出。"], ["这本书", "介绍了", "一位文学家的", "成长经历。"], ["这次的任务", "并不难，", "一个小时", "应该算够了。"], ["这家餐馆", "的厨师", "会做", "地道的家乡菜。"], ["他", "修理自行车", "很有经验，", "可以说是个行家。"], ["为了", "表示感谢，", "她", "亲自做了一桌菜。"], ["讨论时，", "他", "提出了", "自己独特的见解。"], ["他", "对", "中国近代的文学", "很感兴趣。"], ["这本时尚杂志", "介绍了", "今年流行的", "服装风格。"], ["她", "从大学开始", "就", "一直坚持写作。"], ["客人来了，", "妈妈", "端出了一盘", "精致的点心。"], ["作为", "班长，", "他", "总是主动帮助同学。"], ["这位老人", "很有学问，", "我们", "都喜欢听他讲故事。"], ["做事情", "要", "讲究方法，", "不能只靠着急。"], ["大家", "把这笔钱", "平均", "分成了五份。"], ["沿着", "这条胡同", "往前走，", "就能看到那家书店。"], ["这座图书馆", "位于", "城市的", "中心地带。"], ["她", "在晚会上", "为大家", "唱了一首歌。"], ["这家酒店", "装修得很豪华，", "服务", "也很好。"], ["感谢", "您的支持，", "欢迎您", "再次光临本店。"], ["参加", "各种活动，", "可以", "提高我们的交际能力。"], ["他", "待人大方，", "经常", "请朋友们吃饭。"], ["这里的居民", "热情好客，", "让我们", "感到很温暖。"], ["每到周末，", "他", "就呼朋唤友，", "一起到郊外散步。"], ["主人", "准备了丰盛的晚饭，", "热情地", "招待客人。"], ["这家商店", "主要", "出售", "高档家具。"], ["今天", "运动了一个下午，", "我", "胃口特别好。"], ["他", "明明知道答案，", "却", "不愿意告诉大家。"], ["他", "今天", "胃不太舒服，", "只吃了一点儿粥。"], ["为了", "家人的健康，", "他", "决定戒烟。"], ["这些老照片", "保存得很好，", "看起来", "仍然很清楚。"], ["写文章前，", "我们", "需要", "查找相关资料。"], ["她", "曾经", "在这座城市", "工作过三年。"], ["眼前的景色", "太美了，", "我", "不知道该怎样形容。"], ["夜色中，", "远处的灯光", "显得", "十分朦胧。"], ["午后，", "几朵白云", "在蓝天上", "悠悠地飘着。"], ["老师", "用一个小故事，", "形象地", "说明了这个道理。"]];
'use strict';
const root=document.getElementById('ntc-design-preview');
const $=id=>document.getElementById(id);
const STORE='ngocthucac-hsk5-bai9-learning-v3';
const pages=['词汇表','学习生词','词汇卡片','综合练习','连词成句','学习统计'];
let storageOK=true,store={active:null,profiles:{}};
try{let raw=localStorage.getItem(STORE);if(raw){let parsed=JSON.parse(raw);if(parsed&&parsed.profiles)store=parsed}}catch(e){storageOK=false}
let student=store.active?store.profiles[store.active]:null;
if(!student){store.active='local';student=store.profiles.local||createStudent('','');store.profiles.local=student;}
let ui=student?.ui||{page:0,g:0,idx:0,pinyin:false};
let speed=1,playback=null,audioGeneration=0;
const group=g=>WORDS.slice(g*10,g===3?WORDS.length:g*10+10);
const groupOf=id=>Math.min(3,Math.floor(id/10));
const escapeHTML=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const hasLearned=id=>!!student?.studied.includes(id);
const learned=g=>group(g).filter(d=>hasLearned(d.id)).length;
const allLearned=()=>!!student&&student.studied.length===WORDS.length;
const memory=id=>student?.memory[id]||'new';
const weakIds=()=>WORDS.filter(d=>memory(d.id)==='review').map(d=>d.id);
const totalLearned=()=>student?.studied.length||0;
const currentWord=()=>group(ui.g)[ui.idx];
function shuffle(a){let b=[...a];for(let i=b.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]]}return b}
function toast(message){let t=$('ntc-toast');t.textContent=message;t.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.hidden=true,5000)}
function save(){if(student){student.ui={...ui};student.updatedAt=new Date().toISOString()}try{localStorage.setItem(STORE,JSON.stringify(store))}catch(e){storageOK=false;toast('浏览器无法保存学习进度，请允许保存本地数据。')}}
function createStudent(name,clas){return {name,clas,studied:[],memory:{},bookmark:{g:0,idx:0},ui:{page:0,g:0,idx:0,pinyin:false},flash:null,quiz:null,order:null,quizHistory:[],orderHistory:[],timeMs:0}}
function status(id){if(!hasLearned(id))return '<span class="ntc-state new">○ 未学习</span>';if(memory(id)==='review')return '<span class="ntc-state review">↻ 需要复习</span>';return '<span class="ntc-state">✓ 已学习</span>'}
function button(label,action,cls='',disabled=false){return `<button data-action="${action}" class="${cls}" ${disabled?'disabled':''}>${label}</button>`}
function go(page){stopAudio();ui.page=page;if(student&&allLearned()){if(page===2&&!student.flash)startFlash('all',false);if(page===3&&!student.quiz)startQuiz(false);if(page===4&&!student.order)startOrder(null,false)}save();render()}
function chooseGroup(g){stopAudio();ui.g=g;ui.idx=0;ui.page=1;save();render()}
function heading(title,subtitle='',tag=''){return `<div class="ntc-sectionhead"><div><h2>${title}</h2>${subtitle?`<p class="ntc-caption">${subtitle}</p>`:''}</div>${tag?`<span class="ntc-tag">${tag}</span>`:''}</div>`}
function meter(value,total){return `<div class="ntc-meter" role="progressbar" aria-label="进度" aria-valuenow="${value}" aria-valuemin="0" aria-valuemax="${total}"><span style="width:${total?value/total*100:0}%"></span></div>`}
function gate(){return `<div class="ntc-panel ntc-lock"><div class="ntc-kicker">先学习生词，再进行全课复习</div><h2>请先完成生词学习</h2><p>已学习 ${totalLearned()}/38 个词语。学完四组词语后，即可进行词汇卡片、综合练习和连词成句。</p>${meter(totalLearned(),38)}<div class="ntc-progressgroups">${[0,1,2,3].map(g=>`<button data-group="${g}">组别 ${g+1}<br>${learned(g)}/${group(g).length}个词语</button>`).join('')}</div>${button('继续学习 →','resume','ntc-primary')}</div>`}
function listView(){return `<div class="ntc-panel">${heading('词汇表','全课共38个词语，点击 ↗ 学习该词语',totalLearned()+'/38 已学习')}<div class="ntc-tablewrap"><table class="ntc-table"><thead><tr><th>汉字</th><th class="ntc-colpinyin">拼音</th><th class="ntc-coltype">词性</th><th>越南语释义</th><th>状态</th></tr></thead><tbody>${WORDS.map((d,i)=>`<tr><td class="ntc-hanzi">${d.w} <button class="ntc-play" data-word="${i}" aria-label="学习词语 ${d.w}">↗</button><button class="ntc-play" data-audio-word="${i}" aria-label="听词语 ${d.w}">◖</button></td><td class="ntc-colpinyin">${escapeHTML(d.p)}</td><td class="ntc-coltype">${escapeHTML(d.t)}</td><td>${escapeHTML(d.m)}</td><td>${status(i)}</td></tr>`).join('')}</tbody></table></div><div class="ntc-actions"><span class="ntc-caption">仅生词学习分为四组：10、10、10、8个词语。</span>${button('开始／继续学习 →','resume','ntc-primary')}</div></div>`}
function studyView(){let d=currentWord(),a=group(ui.g),isLast=d.id===37;return `<div class="ntc-panel">${heading('学习生词 · 组别 '+(ui.g+1),'学习词语、搭配与例句',`${ui.idx+1}/${a.length}`)}${meter(learned(ui.g),a.length)}<div class="ntc-study"><div class="ntc-wordbox"><div class="ntc-pinyin" style="visibility:${ui.pinyin?'visible':'hidden'}">${escapeHTML(d.p)}</div><div class="ntc-bigword ntc-writing" id="ntc-writing" aria-label="汉字笔顺">${d.w}</div><div class="ntc-meaning">${escapeHTML(d.m)}</div><span class="ntc-type">${escapeHTML(d.t)}</span><div class="ntc-smallbtns">${button('笔顺演示','strokes')}<button data-audio-word="${d.id}">◖ 听词语</button>${button(ui.pinyin?'隐藏拼音':'显示拼音','pinyin')}</div></div><div><div class="ntc-label">常用搭配</div><div class="ntc-cn">${escapeHTML(d.coll)}</div><hr><div class="ntc-label">例句</div><div class="ntc-cn">${escapeHTML(d.s)}</div><div class="ntc-smallbtns"><button data-audio-example="${d.id}">◖ 听例句</button></div><div class="ntc-note">${status(d.id)}</div></div></div><div class="ntc-actions">${button('← 上一个','prev-study','',d.id===0)}${button(isLast?'✓ 已学习 · 全课复习 →':ui.idx===a.length-1?'✓ 已学习 · 下一组 →':'✓ 已学习 · 下一个 →','mark-study','ntc-primary')}</div><div class="ntc-footnote">点击“已学习”记录学习进度。需要时，可点击“笔顺演示”查看汉字的书写顺序。</div></div>`}
function markStudy(){let d=currentWord();if(!student.studied.includes(d.id))student.studied.push(d.id);let next=WORDS.find(x=>!student.studied.includes(x.id));if(d.id<37){let id=d.id+1;ui.g=groupOf(id);ui.idx=id-ui.g*10;student.bookmark={g:ui.g,idx:ui.idx}}else if(!next){ui.page=2;student.bookmark={g:3,idx:7};if(!student.flash)startFlash('all',false)}else{ui.g=groupOf(next.id);ui.idx=next.id-ui.g*10;student.bookmark={g:ui.g,idx:ui.idx};toast('还有未学完的词语，请继续学习。')}save();render()}
function startFlash(filter='all',redraw=true){let ids=filter==='weak'?weakIds():WORDS.map(d=>d.id);if(!ids.length){toast('暂无需要复习的词语。');return}student.flash={filter,ids:shuffle(ids),at:0,flipped:false,ratings:{},done:false};save();if(redraw)render()}
function flashView(){let f=student.flash;if(f.done)f.done=false;let d=WORDS[f.ids[f.at]];return `<div class="ntc-panel">${heading('词汇卡片 · 全课复习',f.filter==='weak'?'复习练习中答错的词语':'全课38个词语随机排列，不分组',`${f.at+1}/${f.ids.length}`)}${meter(f.at+1,f.ids.length)}<div class="ntc-smallbtns" style="margin-bottom:16px">${button('重新打乱全课38个词语','flash-all')}${button('待复习词语 ('+weakIds().length+')','flash-weak','',!weakIds().length)}</div><div class="ntc-flash"><span class="ntc-label">${f.flipped?'背面':'正面'}</span>${f.flipped?`<span class="ntc-pinyin">${escapeHTML(d.p)}</span><span class="ntc-meaning">${escapeHTML(d.m)}</span><span class="ntc-type">${escapeHTML(d.t)}</span><small>${escapeHTML(d.coll)}</small><div class="ntc-note"><span class="ntc-cn">${escapeHTML(d.s)}</span><button class="ntc-play" data-audio-example="${d.id}" aria-label="听例句">◖</button></div>`:`<div style="display:flex;align-items:center;justify-content:center;gap:12px"><span class="ntc-bigword" style="font-size:clamp(40px,${d.w.length>2?'7':'10'}vw,${d.w.length>2?'80':'112'}px)">${d.w}</span><button class="ntc-play" data-audio-word="${d.id}" aria-label="听发音 ${d.w}" title="听发音">🔊</button></div>`}<div class="ntc-smallbtns">${button(f.flipped?'↶ 返回正面':'查看释义与例句 ↻','flip')}</div></div><div class="ntc-actions">${button('← 上一张','flash-prev','',f.at===0)}${f.at===f.ids.length-1?button('综合练习 →','quiz-page','ntc-primary'):button('下一张 →','flash-next','ntc-primary')}</div><div class="ntc-footnote">先看正面回忆词义；需要时翻到背面查看拼音、释义与例句。无需翻面即可切换卡片。</div></div>`}
const contextAlternatives={"0": [6, 28, 33], "1": [6, 28, 33], "2": [6, 28, 33], "3": [6, 28, 33], "4": [6, 28, 33], "5": [6, 28, 33], "6": [6, 28, 33], "7": [6, 28, 33], "8": [6, 28, 33], "9": [6, 28, 33], "10": [6, 28, 33], "11": [6, 28, 33], "12": [6, 28, 33], "13": [6, 28, 33], "14": [6, 28, 33], "15": [6, 28, 33], "16": [6, 28, 33], "17": [6, 28, 33], "18": [6, 28, 33], "19": [6, 28, 33], "20": [6, 28, 33], "21": [6, 28, 33], "22": [6, 28, 33], "23": [6, 28, 33], "24": [6, 28, 33], "25": [6, 28, 33], "26": [6, 28, 33], "27": [6, 28, 33], "28": [6, 28, 33], "29": [6, 28, 33], "30": [6, 28, 33], "31": [6, 28, 33], "32": [6, 28, 33], "33": [6, 28, 33], "34": [6, 28, 33], "35": [6, 28, 33], "36": [6, 28, 33], "37": [6, 28, 33]};
function makeQuestions(ids){let types=ids.map(id=>id%3===2?'context':id%3===0?'listen':'meaning');let positions=shuffle(ids.map((_,i)=>i%4));return shuffle(ids.map((id,i)=>{let alternatives=types[i]==='context'?contextAlternatives[id]:null;let opts=alternatives?shuffle(alternatives):shuffle(WORDS.filter(d=>d.id!==id).map(d=>d.id)).slice(0,3);opts.splice(positions[i],0,id);return {id,type:types[i],opts,correct:positions[i],picked:null}}))}
function startQuiz(redraw=true,ids=null){student.quiz={questions:makeQuestions(ids||WORDS.map(d=>d.id)),at:0,done:false,recorded:false};save();if(redraw)render()}
function quizView(){let q=student.quiz;if(q.done)return quizResults();let x=q.questions[q.at],d=WORDS[x.id],answered=x.picked!==null;return `<div class="ntc-panel">${heading('综合练习','听音选词 · 根据越南语释义选词 · 选词填空',`${q.at+1}/${q.questions.length}题`)}${meter(q.at,q.questions.length)}<div class="ntc-label">${x.type==='listen'?'听一听 · 听音选词':x.type==='meaning'?'认一认 · 根据越南语释义选词':'用一用 · 选词填空'}</div>${x.type==='listen'?`<button data-audio-word="${d.id}" class="ntc-primary">◖ 听词语</button><div class="ntc-footnote">如设备没有中文语音，可切换为根据越南语释义选词。</div>${button('切换为释义题','quiz-as-meaning','',answered)}`:x.type==='meaning'?`<div class="ntc-note">请根据越南语释义选择正确的汉语词语： <strong>${escapeHTML(d.m)}</strong></div>`:`<div class="ntc-cn">${escapeHTML(d.s.replace(d.w,'____'))}</div>`}<div class="ntc-quizopts">${x.opts.map((id,i)=>`<button data-answer="${i}" ${answered?'disabled':''} class="${answered?(i===x.correct?'ntc-correct':i===x.picked?'ntc-wrong':''):''}">${'ABCD'[i]}. ${WORDS[id].w}</button>`).join('')}</div>${answered?`<div class="ntc-note" role="status"><strong>${x.picked===x.correct?'✓ 正确':'✕ 不正确'}</strong><div class="ntc-cn">${d.w} · ${escapeHTML(d.p)}</div>${escapeHTML(d.m)}<br>${escapeHTML(d.s)}</div><div class="ntc-actions"><button data-audio-example="${d.id}">◖ 听例句</button>${button(q.at===q.questions.length-1?'查看结果 →':'下一题 →','quiz-next','ntc-primary')}</div>`:''}</div>`}
function pickQuiz(i){let q=student.quiz,x=q.questions[q.at];if(x.picked!==null)return;x.picked=i;if(i!==x.correct)student.memory[x.id]='review';save();render()}
function nextQuiz(){let q=student.quiz;if(q.questions[q.at].picked===null)return;if(q.at<q.questions.length-1)q.at++;else{q.done=true;if(!q.recorded){student.quizHistory.push({date:new Date().toISOString(),answers:q.questions.map(x=>({id:x.id,ok:x.picked===x.correct})),total:q.questions.length});q.recorded=true}}save();render()}
function quizResults(){let q=student.quiz,wrong=q.questions.filter(x=>x.picked!==x.correct),correct=q.questions.length-wrong.length;return `<div class="ntc-panel">${heading('综合练习结果','正确答案与待复习词语')}<div class="ntc-score">${correct}<small> / ${q.questions.length}题答对</small></div><div class="ntc-tag">${wrong.length}题答错</div>${wrong.map(x=>`<div class="ntc-miniresult"><strong>${WORDS[x.id].w}</strong> · ${escapeHTML(WORDS[x.id].p)}<br>你的选择： ${WORDS[x.opts[x.picked]].w}<br>正确释义： ${escapeHTML(WORDS[x.id].m)}<br>${escapeHTML(WORDS[x.id].s)}</div>`).join('')}<div class="ntc-actions">${button('重新练习全课词语','quiz-restart')}${button('重练错词','quiz-retry','',!wrong.length)}${button('连词成句 →','order-page','ntc-primary')}</div></div>`}
function startOrder(ids=null,redraw=true){let chosen=ids||WORDS.map(d=>d.id);student.order={ids:shuffle(chosen),at:0,bank:[],selected:[],checked:false,answers:[],done:false,recorded:false};newOrderQuestion();save();if(redraw)render()}
function newOrderQuestion(){let o=student.order;o.bank=shuffle(CHUNKS[o.ids[o.at]].map((_,i)=>i));if(o.bank.every((x,i)=>x===i))o.bank.reverse();o.selected=[];o.checked=false}
function orderView(){let o=student.order;if(o.done)return orderResults();let id=o.ids[o.at],d=WORDS[id],chunks=CHUNKS[id],ok=o.selected.every((x,i)=>x===i);return `<div class="ntc-panel">${heading('连词成句 · 全课复习','使用已学的38个例句，题目随机排列',`${o.at+1}/${o.ids.length}题`)}${meter(o.at,o.ids.length)}<div class="ntc-label">重点词语 · ${d.w}</div><p class="ntc-caption">按顺序选择词语，点击已选词语可将其放回。</p><div class="ntc-orderanswer ${o.checked?(ok?'ntc-correct':'ntc-wrong'):''}" aria-label="已排列的句子">${o.selected.length?o.selected.map((index,i)=>`<button data-remove="${i}" ${o.checked?'disabled':''}>${escapeHTML(chunks[index])}</button>`).join(''):'<span class="ntc-caption">请在这里排列句子……</span>'}</div><div class="ntc-chunks" aria-label="待选词语">${o.bank.map(index=>`<button class="${o.selected.includes(index)?'used':''}" data-chunk="${index}" ${o.checked||o.selected.includes(index)?'disabled':''}>${escapeHTML(chunks[index])}</button>`).join('')}</div><div class="ntc-actions"><div class="ntc-smallbtns">${button('↶ 撤销最后一项','order-undo','',!o.selected.length||o.checked)}${button('重新排列','order-clear','',!o.selected.length||o.checked)}</div>${button('检查答案','order-check','ntc-primary',o.selected.length!==chunks.length||o.checked)}</div>${o.checked?`<div class="ntc-note" role="status"><strong>${ok?'✓ 与例句顺序一致':'✕ 与例句顺序不一致'}</strong><div class="ntc-label">原例句</div><div class="ntc-cn">${escapeHTML(d.s)}</div><button data-audio-example="${id}">◖ 听例句</button></div><div class="ntc-actions"><span></span>${button(o.at===o.ids.length-1?'查看结果 →':'下一题 →','order-next','ntc-primary')}</div>`:''}<div class="ntc-footnote">本练习按原例句顺序评分，其他语序也可能符合语法。</div></div>`}
function addChunk(index){let o=student.order;if(o.checked||o.selected.includes(index))return;o.selected.push(index);save();render()}
function removeChunk(index){let o=student.order;if(o.checked)return;o.selected.splice(index,1);save();render()}
function checkOrder(){let o=student.order;if(o.checked||o.selected.length!==CHUNKS[o.ids[o.at]].length)return;o.checked=true;let id=o.ids[o.at],ok=o.selected.every((x,i)=>x===i);o.answers.push({id,ok});if(!ok)student.memory[id]='review';save();render()}
function nextOrder(){let o=student.order;if(!o.checked)return;if(o.at<o.ids.length-1){o.at++;newOrderQuestion()}else{o.done=true;if(!o.recorded){student.orderHistory.push({date:new Date().toISOString(),answers:o.answers.map(x=>({...x})),total:o.ids.length});o.recorded=true}}save();render()}
function orderResults(){let o=student.order,wrong=o.answers.filter(x=>!x.ok).map(x=>x.id),correct=o.answers.length-wrong.length;return `<div class="ntc-panel">${heading('连词成句结果','第9课综合复习')}<div class="ntc-score">${correct}<small> / ${o.answers.length}题答对</small></div><div class="ntc-tag">${wrong.length} 题需要重新练习</div>${wrong.map(id=>`<div class="ntc-miniresult"><strong>${WORDS[id].w}</strong><br><span class="ntc-cn">${escapeHTML(WORDS[id].s)}</span></div>`).join('')}<div class="ntc-actions">${button('重新练习全课句子','order-restart')}${button('重练错题','order-retry','',!wrong.length)}${button('查看学习统计 →','stats-page','ntc-primary')}</div></div>`}
function activityScore(kind,g){let history=kind==='quiz'?student.quizHistory:student.orderHistory,record=history[history.length-1],answers=record?.answers||[],ids=group(g).map(d=>d.id),inGroup=answers.filter(x=>ids.includes(x.id));let active=kind==='quiz'?student.quiz:student.order;if(active&&!active.done){let partial=kind==='quiz'?active.questions.filter(x=>x.picked!==null).map(x=>({id:x.id,ok:x.picked===x.correct})):active.answers;inGroup=partial.filter(x=>ids.includes(x.id));if(inGroup.length)return inGroup.filter(x=>x.ok).length+'/'+inGroup.length+' 进行中'}return inGroup.length?inGroup.filter(x=>x.ok).length+'/'+inGroup.length:'尚未练习'}
function statsView(){let weak=weakIds();return `<div class="ntc-panel">${heading('学习统计','当前浏览器中的第9课学习进度','第9课 · 38个词语')}<div class="ntc-statrow"><div class="ntc-stat"><label>已学词语</label><strong>${totalLearned()}<small> / 38</small></strong></div><div class="ntc-stat"><label>需要复习</label><strong>${weak.length}<small>个词语</small></strong></div></div><div class="ntc-tablewrap"><table class="ntc-table"><thead><tr><th>组别</th><th>已学习</th><th>待复习</th><th>综合练习</th><th>连词成句</th></tr></thead><tbody>${[0,1,2,3].map(g=>`<tr><td>组别 ${g+1}<div class="ntc-caption">${group(g).length}个词语</div></td><td>${learned(g)}/${group(g).length}</td><td>${group(g).filter(d=>memory(d.id)==='review').length}</td><td>${activityScore('quiz',g)}</td><td>${activityScore('order',g)}</td></tr>`).join('')}</tbody></table></div><div class="ntc-footnote">按词语所属组显示答对题数／已答题数。优先显示本轮进度，否则显示最近一轮结果。</div><hr><div class="ntc-sectionhead"><h2>待复习词语</h2>${button('用词汇卡片复习 →','flash-weak','',!weak.length||!allLearned())}</div><div class="ntc-terms">${weak.length?weak.map(id=>`<button data-word="${id}">${WORDS[id].w}</button>`).join(''):'<span class="ntc-caption">暂无需要复习的错词。</span>'}</div><div class="ntc-note">继续学习：组别 ${student.bookmark.g+1} · 词语 ${student.bookmark.idx+1}/${group(student.bookmark.g).length}.<br>本页累计学习时间约 ${Math.floor(student.timeMs/60000)} 分钟。已完成综合练习轮数： ${student.quizHistory.length}; 连词成句轮数： ${student.orderHistory.length}.</div><div class="ntc-actions">${button('继续学习','resume','ntc-primary')}${button('导出学习记录','backup')}${button('恢复学习记录','restore')}</div><div class="ntc-footnote">答错词语会列入待复习词语。浏览词汇卡片不等于掌握词语。</div></div>`}
function render(){clearWriting();let total=totalLearned();$('ntc-profile-button').textContent='HSK5 · 第9课';$('ntc-bookmark').textContent=student?total+'/38 个已学词语':'';$('ntc-tabs').innerHTML=pages.map((name,i)=>`<button class="ntc-tab ${ui.page===i?'active':''}" data-page="${i}" aria-pressed="${ui.page===i}">${i<5?i+1+'. ':''}${name}${i>=2&&i<=4&&!allLearned()?' 🔒':''}</button>`).join('');let showGroups=ui.page===1;$('ntc-groups').hidden=!showGroups;$('ntc-groups').innerHTML=showGroups?[0,1,2,3].map(g=>`<button data-group="${g}" class="${g===ui.g?'active':''}">组别 ${g+1} · ${group(g).length}个词语 · ${learned(g)}/${group(g).length}</button>`).join(''):'';$('ntc-sidegroups').innerHTML=showGroups?'<div class="ntc-navtitle">当前词汇组</div>'+[0,1,2,3].map(g=>`<button class="ntc-sidegroup ${g===ui.g?'active':''}" data-group="${g}"><span>组别 ${g+1}<br><small>词语 ${g*10+1}–${g*10+group(g).length}</small></span><small>${learned(g)}/${group(g).length}</small></button>`).join(''):'<div class="ntc-navtitle">第9课学习进度</div><div style="padding:0 10px">'+total+'/38 个已学词语'+meter(total,38)+'</div>';$('ntc-sidefoot').innerHTML='学完生词 →<br>全课综合复习。<br><br>进度保存在<br>当前浏览器中。';let html;if(ui.page>=2&&ui.page<=4&&!allLearned())html=gate();else html=[listView,studyView,flashView,quizView,orderView,statsView][ui.page]();$('ntc-view').innerHTML=html;if(ui.page===1)setupWriting();}
function stopAudio(){audioGeneration++;if(playback){playback.pause();playback=null}if('speechSynthesis' in window)window.speechSynthesis.cancel()}
const AUDIO_INDEX={"表现":"data:audio/mpeg;base64,","她在这次比赛中表现出色，得到了老师的表扬。":"data:audio/mpeg;base64,","突出":"data:audio/mpeg;base64,","这位同学的学习成绩一直很突出。":"data:audio/mpeg;base64,","文学家":"data:audio/mpeg;base64,","这本书介绍了一位文学家的成长经历。":"data:audio/mpeg;base64,","算":"data:audio/mpeg;base64,","这次的任务并不难，一个小时应该算够了。":"data:audio/mpeg;base64,","地道":"data:audio/mpeg;base64,","这家餐馆的厨师会做地道的家乡菜。":"data:audio/mpeg;base64,","行家":"data:audio/mpeg;base64,","他修理自行车很有经验，可以说是个行家。":"data:audio/mpeg;base64,","亲自":"data:audio/mpeg;base64,","为了表示感谢，她亲自做了一桌菜。":"data:audio/mpeg;base64,","见解":"data:audio/mpeg;base64,","讨论时，他提出了自己独特的见解。":"data:audio/mpeg;base64,","近代":"data:audio/mpeg;base64,","他对中国近代的文学很感兴趣。":"data:audio/mpeg;base64,","时尚":"data:audio/mpeg;base64,","这本时尚杂志介绍了今年流行的服装风格。":"data:audio/mpeg;base64,","写作":"data:audio/mpeg;base64,","她从大学开始就一直坚持写作。":"data:audio/mpeg;base64,","点心":"data:audio/mpeg;base64,","客人来了，妈妈端出了一盘精致的点心。":"data:audio/mpeg;base64,","作为":"data:audio/mpeg;base64,","作为班长，他总是主动帮助同学。":"data:audio/mpeg;base64,","学问":"data:audio/mpeg;base64,","这位老人很有学问，我们都喜欢听他讲故事。":"data:audio/mpeg;base64,","讲究":"data:audio/mpeg;base64,","做事情要讲究方法，不能只靠着急。":"data:audio/mpeg;base64,","平均":"data:audio/mpeg;base64,","大家把这笔钱平均分成了五份。":"data:audio/mpeg;base64,","胡同":"data:audio/mpeg;base64,","沿着这条胡同往前走，就能看到那家书店。":"data:audio/mpeg;base64,","位于":"data:audio/mpeg;base64,","这座图书馆位于城市的中心地带。":"data:audio/mpeg;base64,","首":"data:audio/mpeg;base64,","她在晚会上为大家唱了一首歌。":"data:audio/mpeg;base64,","豪华":"data:audio/mpeg;base64,","这家酒店装修得很豪华，服务也很好。":"data:audio/mpeg;base64,","光临":"data:audio/mpeg;base64,","感谢您的支持，欢迎您再次光临本店。":"data:audio/mpeg;base64,","交际":"data:audio/mpeg;base64,","参加各种活动，可以提高我们的交际能力。":"data:audio/mpeg;base64,","大方":"data:audio/mpeg;base64,","他待人大方，经常请朋友们吃饭。":"data:audio/mpeg;base64,","好客":"data:audio/mpeg;base64,","这里的居民热情好客，让我们感到很温暖。":"data:audio/mpeg;base64,","呼朋唤友":"data:audio/mpeg;base64,","每到周末，他就呼朋唤友，一起到郊外散步。":"data:audio/mpeg;base64,","招待":"data:audio/mpeg;base64,","主人准备了丰盛的晚饭，热情地招待客人。":"data:audio/mpeg;base64,","高档":"data:audio/mpeg;base64,","这家商店主要出售高档家具。":"data:audio/mpeg;base64,","胃口":"data:audio/mpeg;base64,","今天运动了一个下午，我胃口特别好。":"data:audio/mpeg;base64,","明明":"data:audio/mpeg;base64,","他明明知道答案，却不愿意告诉大家。":"data:audio/mpeg;base64,","胃":"data:audio/mpeg;base64,","他今天胃不太舒服，只吃了一点儿粥。":"data:audio/mpeg;base64,","戒":"data:audio/mpeg;base64,","为了家人的健康，他决定戒烟。":"data:audio/mpeg;base64,","保存":"data:audio/mpeg;base64,","这些老照片保存得很好，看起来仍然很清楚。":"data:audio/mpeg;base64,","资料":"data:audio/mpeg;base64,","写文章前，我们需要查找相关资料。":"data:audio/mpeg;base64,","曾经":"data:audio/mpeg;base64,","她曾经在这座城市工作过三年。":"data:audio/mpeg;base64,","形容":"data:audio/mpeg;base64,","眼前的景色太美了，我不知道该怎样形容。":"data:audio/mpeg;base64,","朦胧":"data:audio/mpeg;base64,","夜色中，远处的灯光显得十分朦胧。":"data:audio/mpeg;base64,","悠悠":"data:audio/mpeg;base64,","午后，几朵白云在蓝天上悠悠地飘着。":"data:audio/mpeg;base64,","形象":"data:audio/mpeg;base64,","老师用一个小故事，形象地说明了这个道理。":"data:audio/mpeg;base64,"};
function speak(text){stopAudio();const path=AUDIO_INDEX[text];if(!path){toast('未找到此内容的配套音频。');return}const generation=audioGeneration;const player=new Audio(path);playback=player;player.playbackRate=speed;player.onerror=()=>{if(generation===audioGeneration){$('ntc-voice-label').textContent='音频未加载';toast('无法加载音频，请确认 HTML 与 audio 文件夹一起保存或上传。')}};player.onended=()=>{if(playback===player)playback=null};player.play().then(()=>{if(generation!==audioGeneration){player.pause();return}$('ntc-voice-label').textContent='朗读：Xiaoxiao · 固定 MP3';}).catch(()=>{if(generation===audioGeneration)toast('音频暂时无法播放，请确认音频文件存在后再次点击。')})}
function backup(){const content=JSON.stringify({format:'ntc-hsk5-bai9-v3',profile:student},null,2);let url=URL.createObjectURL(new Blob([content],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='HSK5_Bai9_TienDo.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function restore(){let input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.addEventListener('change',async()=>{try{let v=JSON.parse(await input.files[0].text()),p=v.profile;if(v.format!=='ntc-hsk5-bai9-v3'||!p||typeof p.name!=='string'||typeof p.clas!=='string'||!Array.isArray(p.studied)||p.studied.some(id=>!Number.isInteger(id)||id<0||id>=38)||!p.memory)throw Error();if(!confirm('恢复第9课学习记录？当前记录将被替换。'))return;let id=store.active||'local';let clean=createStudent(p.name,p.clas);clean.studied=[...new Set(p.studied)];for(let k=0;k<38;k++)if(['remembered','review'].includes(p.memory[k]))clean.memory[k]=p.memory[k];if(p.bookmark&&Number.isInteger(p.bookmark.g)&&p.bookmark.g>=0&&p.bookmark.g<4&&Number.isInteger(p.bookmark.idx)&&p.bookmark.idx>=0&&p.bookmark.idx<group(p.bookmark.g).length)clean.bookmark=p.bookmark;for(let key of ['quizHistory','orderHistory'])if(Array.isArray(p[key]))clean[key]=p[key].filter(r=>r&&Array.isArray(r.answers)&&r.answers.every(a=>Number.isInteger(a.id)&&a.id>=0&&a.id<38&&typeof a.ok==='boolean'));clean.timeMs=Math.max(0,Number(p.timeMs)||0);store.profiles[id]=clean;store.active=id;student=clean;ui={page:5,g:0,idx:0,pinyin:false};save();render();toast('已恢复已学词语、复习状态与练习记录。')}catch(e){toast('无法读取有效的HSK5第9课学习记录。')}});input.click()}
root.addEventListener('click',event=>{let b=event.target.closest('button');if(!b||b.disabled)return;const data=b.dataset;if(data.audioWord!==undefined){speak(WORDS[+data.audioWord].w);return}if(data.audioExample!==undefined){speak(WORDS[+data.audioExample].s);return}if(data.page!==undefined){go(+data.page);return}if(data.group!==undefined){chooseGroup(+data.group);return}if(data.word!==undefined){let id=+data.word;ui.g=groupOf(id);ui.idx=id-ui.g*10;go(1);return}if(data.answer!==undefined){stopAudio();pickQuiz(+data.answer);return}if(data.chunk!==undefined){addChunk(+data.chunk);return}if(data.remove!==undefined){removeChunk(+data.remove);return}let a=data.action;if(!a)return;if(a==='stop'){stopAudio();return}switch(a){case'strokes':animateWriting();return;case'resume':ui.g=student.bookmark.g;ui.idx=student.bookmark.idx;go(1);return;case'pinyin':ui.pinyin=!ui.pinyin;break;case'prev-study':{let id=currentWord().id-1;ui.g=groupOf(id);ui.idx=id-ui.g*10;break}case'mark-study':stopAudio();markStudy();return;case'flip':student.flash.flipped=!student.flash.flipped;break;case'flash-all':if(!allLearned()){go(2);return}ui.page=2;startFlash('all');return;case'flash-weak':if(!allLearned()){go(2);return}ui.page=2;startFlash('weak');return;case'flash-prev':student.flash.at--;student.flash.flipped=false;break;case'flash-next':student.flash.at++;student.flash.flipped=false;break;case'quiz-page':go(3);return;case'order-page':go(4);return;case'stats-page':go(5);return;case'quiz-as-meaning':student.quiz.questions[student.quiz.at].type='meaning';break;case'quiz-next':stopAudio();nextQuiz();return;case'quiz-restart':startQuiz();return;case'quiz-retry':startQuiz(true,student.quiz.questions.filter(x=>x.picked!==x.correct).map(x=>x.id));return;case'order-undo':removeChunk(student.order.selected.length-1);return;case'order-clear':student.order.selected=[];break;case'order-check':checkOrder();return;case'order-next':stopAudio();nextOrder();return;case'order-restart':startOrder();return;case'order-retry':startOrder(student.order.answers.filter(x=>!x.ok).map(x=>x.id));return;case'backup':backup();return;case'restore':restore();return;default:return}save();render()});
root.addEventListener('change',event=>{if(event.target.id==='ntc-rate')speed=Number(event.target.value)});


let strokeWriters=[],strokeRun=0;
function clearWriting(){strokeRun++;for(const w of strokeWriters){w.pauseAnimation();}strokeWriters=[];}
function setupWriting(){const box=$('ntc-writing');if(!box)return;box.innerHTML='';for(const c of currentWord().w){const el=document.createElement('span');el.setAttribute('aria-label',c);box.appendChild(el);if(!STROKE_DATA[c]||typeof HanziWriter==='undefined'){el.textContent=c;if(!/[\u4e00-\u9fff]/.test(c)){el.style.width='24px';el.style.fontSize='30px';}continue;}strokeWriters.push(HanziWriter.create(el,c,{width:92,height:106,padding:3,strokeColor:'#a3455d',radicalColor:'#a3455d',outlineColor:'#ecd2db',strokeAnimationSpeed:0.7,delayBetweenStrokes:180,charDataLoader:()=>STROKE_DATA[c]}));}}
async function animateWriting(){const token=++strokeRun,list=[...strokeWriters];if(!list.length){toast('暂时无法显示笔顺。');return;}const button=root.querySelector('[data-action="strokes"]');if(button)button.disabled=true;try{for(const w of list)await w.hideCharacter({duration:0});for(const w of list){if(token!==strokeRun)return;await w.animateCharacter();}}finally{if(token===strokeRun&&button)button.disabled=false;}}

let lastTick=Date.now();setInterval(()=>{let now=Date.now();if(student&&!document.hidden){student.timeMs+=Math.min(now-lastTick,15000);save()}lastTick=now},15000);
window.addEventListener('pagehide',()=>{save();stopAudio()});
if(student&&ui.page>=2&&ui.page<=4&&allLearned()){if(ui.page===2&&!student.flash)startFlash('all',false);if(ui.page===3&&!student.quiz)startQuiz(false);if(ui.page===4&&!student.order)startOrder(null,false)}
save();render();if(!storageOK)toast('浏览器阻止保存数据，建议导出学习记录作为备份。');

